window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-e2f23961438a99d3"]={"versions": [{"id": "FIG-e2f23961438a99d3", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> Zeitverlaufsdiagramm / Timing-Diagramm (Signallauf- und Kanalzustandsdiagramm über der Zeitachse t).\n</li><li><strong>Architektur-Einordnung:</strong> AUTOSAR Classic Platform, Microcontroller Abstraction Layer (MCAL), Modul <strong>GPT Driver</strong> (<code>Gpt</code>, General Purpose Timer Driver).\n</li><li><strong>Technischer Zweck:</strong> Spezifikation des Kanalverhaltens, des Zählerstands (<code>timer value</code>) und der diskreten Kanalzustände eines GPT-Hardware-/Software-Kanals im Einmal-Modus (<strong>One-Shot Mode</strong>, Konfigurationsparameter <code>GptChannelMode = GPT_CH_MODE_ONESHOT</code>) bei Aufruf der Steuerungs-APIs <code>Gpt_StartTimer()</code> und <code>Gpt_StopTimer()</code>.\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Entitäten &amp; Zustände (Kanal-Zustandsmodell):</strong>\n<ul class=\"fig-list\"><li><code>initialized</code>: Kanal nach <code>Gpt_Init()</code> initialisiert, Zähler ruht auf <code>0</code>.\n</li><li><code>running</code>: Zähler zählt aktiv aufwärts (<code>timer value</code> steigt linear) in Richtung des übergebenen Zielwerts (<code>target time</code>).\n</li><li><code>expired</code>: Zähler hat <code>target time</code> erreicht. Im One-Shot-Modus stoppt die Hardware/Software-Zählung automatisch; der Endwert bleibt gehalten.\n</li><li><code>stopped</code>: Zähler wurde vor Ablauf durch Software manuell angehalten; der erreichte Zwischenwert bleibt eingefroren.\n</li></ul>\n</li><li><strong>Schnittstellen &amp; Parameter:</strong>\n<ul class=\"fig-list\"><li><code>Gpt_StartTimer(Gpt_ChannelType Channel, Gpt_ValueType Value)</code>: Startet oder reinitialisiert den Kanal ab Relativwert <code>0</code> bis zum Zielwert <code>target time</code> (Value).\n</li><li><code>Gpt_StopTimer(Gpt_ChannelType Channel)</code>: Stoppt die Zählung asynchron/synchron; fixiert den aktuellen Zählerstand.\n</li></ul>\n</li><li><strong>Datenstrukturen &amp; Attribute:</strong>\n<ul class=\"fig-list\"><li><code>timer value</code>: Hardware-Zählerregister bzw. software-emulierter Kanalwert (0 ≤ value ≤ target time).\n</li><li><code>target time</code> (1, 2, 3): Übergebene relative Zielzeit (Ticks), repräsentiert durch <code>Gpt_ValueType</code>.\n</li></ul>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Initial-Zustand (<code>initialized</code>):</strong>\n<ul class=\"fig-list\"><li>Voraussetzung: <code>Gpt_Init()</code> erfolgreich ausgeführt. Zählerstand verharrt auf <code>0</code>.\n</li></ul>\n</li><li><strong>Erster Zählzyklus (<code>Gpt_StartTimer 1</code> → <code>expired</code>):</strong>\n<ul class=\"fig-list\"><li>Aufruf von <code>Gpt_StartTimer(Channel, target time 1)</code>.\n</li><li>Zustandsübergang: <code>initialized</code> → <code>running</code>.\n</li><li>Zählerstand steigt deterministisch von <code>0</code> bis <code>target time 1</code>.\n</li><li>Bei Erreichen von <code>target time 1</code>: Automatischer Stop des Zählers, Übergang <code>running</code> → <code>expired</code>.\n</li><li>Falls Benachrichtigung über <code>Gpt_EnableNotification(Channel)</code> aktiviert ist, erfolgt an diesem Punkt der asynchrone Interrupt-Callback (<code>GptNotification</code>).\n</li><li>Zählerstand verbleibt bis zum nächsten API-Aufruf auf <code>target time 1</code>.\n</li></ul>\n</li><li><strong>Zweiter Zählzyklus mit vorzeitigem Abbruch (<code>Gpt_StartTimer 2</code> → <code>stopped</code>):</strong>\n<ul class=\"fig-list\"><li>Aufruf von <code>Gpt_StartTimer(Channel, target time 2)</code>.\n</li><li>Zähler wird unmittelbar auf <code>0</code> zurückgesetzt; Übergang <code>expired</code> → <code>running</code>.\n</li><li>Zähler läuft in Richtung <code>target time 2</code>.\n</li><li>Vor Erreichen des Zielwerts erfolgt der Aufruf von <code>Gpt_StopTimer(Channel)</code>.\n</li><li>Übergang <code>running</code> → <code>stopped</code>. Die Zählung wird eingefroren; es wird <strong>kein</strong> Ablauf-Callback ausgelöst.\n</li></ul>\n</li><li><strong>Dritter Zählzyklus (<code>Gpt_StartTimer 3</code> → <code>expired</code>):</strong>\n<ul class=\"fig-list\"><li>Aufruf von <code>Gpt_StartTimer(Channel, target time 3)</code>.\n</li><li>Zähler wird aus dem Zustand <code>stopped</code> wieder auf <code>0</code> zurückgesetzt; Übergang <code>stopped</code> → <code>running</code>.\n</li><li>Zähler läuft linear bis <code>target time 3</code> und wechselt bei Zielerreichung wieder nach <code>expired</code> (Zählerstand bleibt auf <code>target time 3</code> stehen, ggf. Callback).\n</li></ul>\n</li></ol>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Automatischer Stopp:</strong> Im Gegensatz zum <code>GPT_CH_MODE_CONTINUOUS</code> erfolgt kein Rollover auf <code>0</code> und kein automatischer Neustart des Timers. Der Kanal verbleibt nach Zielerreichung inaktiv im Zustand <code>expired</code>.\n</li><li><strong>Re-Start-Verhalten:</strong> Jeder Aufruf von <code>Gpt_StartTimer()</code> auf einen bereits laufenden, angehaltenen oder abgelaufenen Kanal setzt den Zählerwert implizit auf <code>0</code> zurück.\n</li><li><strong>Abfrage von Rest- und Ablaufzeiten:</strong>\n<ul class=\"fig-list\"><li><code>Gpt_GetTimeElapsed()</code>: Liefert im Zustand <code>running</code> die bisher verstrichene Zeit ab <code>0</code>. Im Zustand <code>expired</code> liefert die Funktion normativ den vollen Zielwert (<code>target time</code>). Im Zustand <code>stopped</code> liefert sie den eingefrorenen Zwischenwert zum Zeitpunkt von <code>Gpt_StopTimer()</code>.\n</li><li><code>Gpt_GetTimeRemaining()</code>: Liefert im Zustand <code>running</code> (target time - timer value). Im Zustand <code>expired</code> ist der Rückgabewert <code>0</code>.\n</li></ul>\n</li><li><strong>Einschränkungen &amp; Fehlerbehandlung:</strong>\n<ul class=\"fig-list\"><li>Ein erneuter Aufruf von <code>Gpt_StartTimer()</code> auf einen Kanal im Zustand <code>running</code> erfordert die Einhaltung der Re-Entranz- und Zustandskonventionen (ggf. DET-Fehler <code>GPT_E_ALREADY_RUNNING</code>, sofern im Treiber so konfiguriert/spezifiziert).\n</li><li><code>Gpt_StopTimer()</code> auf einen nicht laufenden Kanal (<code>initialized</code>, <code>stopped</code>, <code>expired</code>) ist idempotent bzw. darf zu keinem undefinierten Hardwarezustand führen (prüfen auf DET-Meldung <code>GPT_E_PARAM_CHANNEL</code> oder Statusprüfung).\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-188d25463dd994b3", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> Zeitverlaufsdiagramm / Timing-Diagramm (Signallauf- und Kanalzustandsdiagramm über der Zeitachse t).\n</li><li><strong>Architektur-Einordnung:</strong> AUTOSAR Classic Platform, Microcontroller Abstraction Layer (MCAL), Modul <strong>GPT Driver</strong> (<code>Gpt</code>, General Purpose Timer Driver).\n</li><li><strong>Technischer Zweck:</strong> Spezifikation des Kanalverhaltens, des Zählerstands (<code>timer value</code>) und der diskreten Kanalzustände eines GPT-Hardware-/Software-Kanals im Einmal-Modus (<strong>One-Shot Mode</strong>, Konfigurationsparameter <code>GptChannelMode = GPT_CH_MODE_ONESHOT</code>) bei Aufruf der Steuerungs-APIs <code>Gpt_StartTimer()</code> und <code>Gpt_StopTimer()</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Entitäten &amp; Zustände (Kanal-Zustandsmodell):</strong>\n<ul class=\"fig-list\"><li><code>initialized</code>: Kanal nach <code>Gpt_Init()</code> initialisiert, Zähler ruht auf <code>0</code>.\n</li><li><code>running</code>: Zähler zählt aktiv aufwärts (<code>timer value</code> steigt linear) in Richtung des übergebenen Zielwerts (<code>target time</code>).\n</li><li><code>expired</code>: Zähler hat <code>target time</code> erreicht. Im One-Shot-Modus stoppt die Hardware/Software-Zählung automatisch; der Endwert bleibt gehalten.\n</li><li><code>stopped</code>: Zähler wurde vor Ablauf durch Software manuell angehalten; der erreichte Zwischenwert bleibt eingefroren.\n</li></ul>\n</li><li><strong>Schnittstellen &amp; Parameter:</strong>\n<ul class=\"fig-list\"><li><code>Gpt_StartTimer(Gpt_ChannelType Channel, Gpt_ValueType Value)</code>: Startet oder reinitialisiert den Kanal ab Relativwert <code>0</code> bis zum Zielwert <code>target time</code> (Value).\n</li><li><code>Gpt_StopTimer(Gpt_ChannelType Channel)</code>: Stoppt die Zählung asynchron/synchron; fixiert den aktuellen Zählerstand.\n</li></ul>\n</li><li><strong>Datenstrukturen &amp; Attribute:</strong>\n<ul class=\"fig-list\"><li><code>timer value</code>: Hardware-Zählerregister bzw. software-emulierter Kanalwert (0 ≤ value ≤ target time).\n</li><li><code>target time</code> (1, 2, 3): Übergebene relative Zielzeit (Ticks), repräsentiert durch <code>Gpt_ValueType</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Initial-Zustand (<code>initialized</code>):</strong>\n<ul class=\"fig-list\"><li>Voraussetzung: <code>Gpt_Init()</code> erfolgreich ausgeführt. Zählerstand verharrt auf <code>0</code>.\n</li></ul>\n</li><li><strong>Erster Zählzyklus (<code>Gpt_StartTimer 1</code> → <code>expired</code>):</strong>\n<ul class=\"fig-list\"><li>Aufruf von <code>Gpt_StartTimer(Channel, target time 1)</code>.\n</li><li>Zustandsübergang: <code>initialized</code> → <code>running</code>.\n</li><li>Zählerstand steigt deterministisch von <code>0</code> bis <code>target time 1</code>.\n</li><li>Bei Erreichen von <code>target time 1</code>: Automatischer Stop des Zählers, Übergang <code>running</code> → <code>expired</code>.\n</li><li>Falls Benachrichtigung über <code>Gpt_EnableNotification(Channel)</code> aktiviert ist, erfolgt an diesem Punkt der asynchrone Interrupt-Callback (<code>GptNotification</code>).\n</li><li>Zählerstand verbleibt bis zum nächsten API-Aufruf auf <code>target time 1</code>.\n</li></ul>\n</li><li><strong>Zweiter Zählzyklus mit vorzeitigem Abbruch (<code>Gpt_StartTimer 2</code> → <code>stopped</code>):</strong>\n<ul class=\"fig-list\"><li>Aufruf von <code>Gpt_StartTimer(Channel, target time 2)</code>.\n</li><li>Zähler wird unmittelbar auf <code>0</code> zurückgesetzt; Übergang <code>expired</code> → <code>running</code>.\n</li><li>Zähler läuft in Richtung <code>target time 2</code>.\n</li><li>Vor Erreichen des Zielwerts erfolgt der Aufruf von <code>Gpt_StopTimer(Channel)</code>.\n</li><li>Übergang <code>running</code> → <code>stopped</code>. Die Zählung wird eingefroren; es wird <strong>kein</strong> Ablauf-Callback ausgelöst.\n</li></ul>\n</li><li><strong>Dritter Zählzyklus (<code>Gpt_StartTimer 3</code> → <code>expired</code>):</strong>\n<ul class=\"fig-list\"><li>Aufruf von <code>Gpt_StartTimer(Channel, target time 3)</code>.\n</li><li>Zähler wird aus dem Zustand <code>stopped</code> wieder auf <code>0</code> zurückgesetzt; Übergang <code>stopped</code> → <code>running</code>.\n</li><li>Zähler läuft linear bis <code>target time 3</code> und wechselt bei Zielerreichung wieder nach <code>expired</code> (Zählerstand bleibt auf <code>target time 3</code> stehen, ggf. Callback).\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Automatischer Stopp:</strong> Im Gegensatz zum <code>GPT_CH_MODE_CONTINUOUS</code> erfolgt kein Rollover auf <code>0</code> und kein automatischer Neustart des Timers. Der Kanal verbleibt nach Zielerreichung inaktiv im Zustand <code>expired</code>.\n</li><li><strong>Re-Start-Verhalten:</strong> Jeder Aufruf von <code>Gpt_StartTimer()</code> auf einen bereits laufenden, angehaltenen oder abgelaufenen Kanal setzt den Zählerwert implizit auf <code>0</code> zurück.\n</li><li><strong>Abfrage von Rest- und Ablaufzeiten:</strong>\n<ul class=\"fig-list\"><li><code>Gpt_GetTimeElapsed()</code>: Liefert im Zustand <code>running</code> die bisher verstrichene Zeit ab <code>0</code>. Im Zustand <code>expired</code> liefert die Funktion normativ den vollen Zielwert (<code>target time</code>). Im Zustand <code>stopped</code> liefert sie den eingefrorenen Zwischenwert zum Zeitpunkt von <code>Gpt_StopTimer()</code>.\n</li><li><code>Gpt_GetTimeRemaining()</code>: Liefert im Zustand <code>running</code> (target time - timer value). Im Zustand <code>expired</code> ist der Rückgabewert <code>0</code>.\n</li></ul>\n</li><li><strong>Einschränkungen &amp; Fehlerbehandlung:</strong>\n<ul class=\"fig-list\"><li>Ein erneuter Aufruf von <code>Gpt_StartTimer()</code> auf einen Kanal im Zustand <code>running</code> erfordert die Einhaltung der Re-Entranz- und Zustandskonventionen (ggf. DET-Fehler <code>GPT_E_ALREADY_RUNNING</code>, sofern im Treiber so konfiguriert/spezifiziert).\n</li><li><code>Gpt_StopTimer()</code> auf einen nicht laufenden Kanal (<code>initialized</code>, <code>stopped</code>, <code>expired</code>) ist idempotent bzw. darf zu keinem undefinierten Hardwarezustand führen (prüfen auf DET-Meldung <code>GPT_E_PARAM_CHANNEL</code> oder Statusprüfung).\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-452b75e78c57ec25", "releases": ["R4.2.2", "R4.3.1", "R18-10_R4.4.0_R1.5.0", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> Zeitverlaufsdiagramm / Timing-Diagramm (Signallauf- und Kanalzustandsdiagramm über der Zeitachse t).\n</li><li><strong>Architektur-Einordnung:</strong> AUTOSAR Classic Platform, Microcontroller Abstraction Layer (MCAL), Modul <strong>GPT Driver</strong> (<code>Gpt</code>, General Purpose Timer Driver).\n</li><li><strong>Technischer Zweck:</strong> Spezifikation des Kanalverhaltens, des Zählerstands (<code>timer value</code>) und der diskreten Kanalzustände eines GPT-Hardware-/Software-Kanals im Einmal-Modus (<strong>One-Shot Mode</strong>, Konfigurationsparameter <code>GptChannelMode = GPT_CH_MODE_ONESHOT</code>) bei Aufruf der Steuerungs-APIs <code>Gpt_StartTimer()</code> und <code>Gpt_StopTimer()</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Entitäten &amp; Zustände (Kanal-Zustandsmodell):</strong>\n<ul class=\"fig-list\"><li><code>initialized</code>: Kanal nach <code>Gpt_Init()</code> initialisiert, Zähler ruht auf <code>0</code>.\n</li><li><code>running</code>: Zähler zählt aktiv aufwärts (<code>timer value</code> steigt linear) in Richtung des übergebenen Zielwerts (<code>target time</code>).\n</li><li><code>expired</code>: Zähler hat <code>target time</code> erreicht. Im One-Shot-Modus stoppt die Hardware/Software-Zählung automatisch; der Endwert bleibt gehalten.\n</li><li><code>stopped</code>: Zähler wurde vor Ablauf durch Software manuell angehalten; der erreichte Zwischenwert bleibt eingefroren.\n</li></ul>\n</li><li><strong>Schnittstellen &amp; Parameter:</strong>\n<ul class=\"fig-list\"><li><code>Gpt_StartTimer(Gpt_ChannelType Channel, Gpt_ValueType Value)</code>: Startet oder reinitialisiert den Kanal ab Relativwert <code>0</code> bis zum Zielwert <code>target time</code> (Value).\n</li><li><code>Gpt_StopTimer(Gpt_ChannelType Channel)</code>: Stoppt die Zählung asynchron/synchron; fixiert den aktuellen Zählerstand.\n</li></ul>\n</li><li><strong>Datenstrukturen &amp; Attribute:</strong>\n<ul class=\"fig-list\"><li><code>timer value</code>: Hardware-Zählerregister bzw. software-emulierter Kanalwert (0 ≤ value ≤ target time).\n</li><li><code>target time</code> (1, 2, 3): Übergebene relative Zielzeit (Ticks), repräsentiert durch <code>Gpt_ValueType</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Initial-Zustand (<code>initialized</code>):</strong>\n<ul class=\"fig-list\"><li>Voraussetzung: <code>Gpt_Init()</code> erfolgreich ausgeführt. Zählerstand verharrt auf <code>0</code>.\n</li></ul>\n</li><li><strong>Erster Zählzyklus (<code>Gpt_StartTimer 1</code> → <code>expired</code>):</strong>\n<ul class=\"fig-list\"><li>Aufruf von <code>Gpt_StartTimer(Channel, target time 1)</code>.\n</li><li>Zustandsübergang: <code>initialized</code> → <code>running</code>.\n</li><li>Zählerstand steigt deterministisch von <code>0</code> bis <code>target time 1</code>.\n</li><li>Bei Erreichen von <code>target time 1</code>: Automatischer Stop des Zählers, Übergang <code>running</code> → <code>expired</code>.\n</li><li>Falls Benachrichtigung über <code>Gpt_EnableNotification(Channel)</code> aktiviert ist, erfolgt an diesem Punkt der asynchrone Interrupt-Callback (<code>GptNotification</code>).\n</li><li>Zählerstand verbleibt bis zum nächsten API-Aufruf auf <code>target time 1</code>.\n</li></ul>\n</li><li><strong>Zweiter Zählzyklus mit vorzeitigem Abbruch (<code>Gpt_StartTimer 2</code> → <code>stopped</code>):</strong>\n<ul class=\"fig-list\"><li>Aufruf von <code>Gpt_StartTimer(Channel, target time 2)</code>.\n</li><li>Zähler wird unmittelbar auf <code>0</code> zurückgesetzt; Übergang <code>expired</code> → <code>running</code>.\n</li><li>Zähler läuft in Richtung <code>target time 2</code>.\n</li><li>Vor Erreichen des Zielwerts erfolgt der Aufruf von <code>Gpt_StopTimer(Channel)</code>.\n</li><li>Übergang <code>running</code> → <code>stopped</code>. Die Zählung wird eingefroren; es wird <strong>kein</strong> Ablauf-Callback ausgelöst.\n</li></ul>\n</li><li><strong>Dritter Zählzyklus (<code>Gpt_StartTimer 3</code> → <code>expired</code>):</strong>\n<ul class=\"fig-list\"><li>Aufruf von <code>Gpt_StartTimer(Channel, target time 3)</code>.\n</li><li>Zähler wird aus dem Zustand <code>stopped</code> wieder auf <code>0</code> zurückgesetzt; Übergang <code>stopped</code> → <code>running</code>.\n</li><li>Zähler läuft linear bis <code>target time 3</code> und wechselt bei Zielerreichung wieder nach <code>expired</code> (Zählerstand bleibt auf <code>target time 3</code> stehen, ggf. Callback).\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Automatischer Stopp:</strong> Im Gegensatz zum <code>GPT_CH_MODE_CONTINUOUS</code> erfolgt kein Rollover auf <code>0</code> und kein automatischer Neustart des Timers. Der Kanal verbleibt nach Zielerreichung inaktiv im Zustand <code>expired</code>.\n</li><li><strong>Re-Start-Verhalten:</strong> Jeder Aufruf von <code>Gpt_StartTimer()</code> auf einen bereits laufenden, angehaltenen oder abgelaufenen Kanal setzt den Zählerwert implizit auf <code>0</code> zurück.\n</li><li><strong>Abfrage von Rest- und Ablaufzeiten:</strong>\n<ul class=\"fig-list\"><li><code>Gpt_GetTimeElapsed()</code>: Liefert im Zustand <code>running</code> die bisher verstrichene Zeit ab <code>0</code>. Im Zustand <code>expired</code> liefert die Funktion normativ den vollen Zielwert (<code>target time</code>). Im Zustand <code>stopped</code> liefert sie den eingefrorenen Zwischenwert zum Zeitpunkt von <code>Gpt_StopTimer()</code>.\n</li><li><code>Gpt_GetTimeRemaining()</code>: Liefert im Zustand <code>running</code> (target time - timer value). Im Zustand <code>expired</code> ist der Rückgabewert <code>0</code>.\n</li></ul>\n</li><li><strong>Einschränkungen &amp; Fehlerbehandlung:</strong>\n<ul class=\"fig-list\"><li>Ein erneuter Aufruf von <code>Gpt_StartTimer()</code> auf einen Kanal im Zustand <code>running</code> erfordert die Einhaltung der Re-Entranz- und Zustandskonventionen (ggf. DET-Fehler <code>GPT_E_ALREADY_RUNNING</code>, sofern im Treiber so konfiguriert/spezifiziert).\n</li><li><code>Gpt_StopTimer()</code> auf einen nicht laufenden Kanal (<code>initialized</code>, <code>stopped</code>, <code>expired</code>) ist idempotent bzw. darf zu keinem undefinierten Hardwarezustand führen (prüfen auf DET-Meldung <code>GPT_E_PARAM_CHANNEL</code> oder Statusprüfung).\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-482483b750955172", "releases": ["R20-11", "R21-11", "R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> Zeitverlaufsdiagramm / Timing-Diagramm (Signallauf- und Kanalzustandsdiagramm über der Zeitachse t).\n</li><li><strong>Architektur-Einordnung:</strong> AUTOSAR Classic Platform, Microcontroller Abstraction Layer (MCAL), Modul <strong>GPT Driver</strong> (<code>Gpt</code>, General Purpose Timer Driver).\n</li><li><strong>Technischer Zweck:</strong> Spezifikation des Kanalverhaltens, des Zählerstands (<code>timer value</code>) und der diskreten Kanalzustände eines GPT-Hardware-/Software-Kanals im Einmal-Modus (<strong>One-Shot Mode</strong>, Konfigurationsparameter <code>GptChannelMode = GPT_CH_MODE_ONESHOT</code>) bei Aufruf der Steuerungs-APIs <code>Gpt_StartTimer()</code> und <code>Gpt_StopTimer()</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Entitäten &amp; Zustände (Kanal-Zustandsmodell):</strong>\n<ul class=\"fig-list\"><li><code>initialized</code>: Kanal nach <code>Gpt_Init()</code> initialisiert, Zähler ruht auf <code>0</code>.\n</li><li><code>running</code>: Zähler zählt aktiv aufwärts (<code>timer value</code> steigt linear) in Richtung des übergebenen Zielwerts (<code>target time</code>).\n</li><li><code>expired</code>: Zähler hat <code>target time</code> erreicht. Im One-Shot-Modus stoppt die Hardware/Software-Zählung automatisch; der Endwert bleibt gehalten.\n</li><li><code>stopped</code>: Zähler wurde vor Ablauf durch Software manuell angehalten; der erreichte Zwischenwert bleibt eingefroren.\n</li></ul>\n</li><li><strong>Schnittstellen &amp; Parameter:</strong>\n<ul class=\"fig-list\"><li><code>Gpt_StartTimer(Gpt_ChannelType Channel, Gpt_ValueType Value)</code>: Startet oder reinitialisiert den Kanal ab Relativwert <code>0</code> bis zum Zielwert <code>target time</code> (Value).\n</li><li><code>Gpt_StopTimer(Gpt_ChannelType Channel)</code>: Stoppt die Zählung asynchron/synchron; fixiert den aktuellen Zählerstand.\n</li></ul>\n</li><li><strong>Datenstrukturen &amp; Attribute:</strong>\n<ul class=\"fig-list\"><li><code>timer value</code>: Hardware-Zählerregister bzw. software-emulierter Kanalwert (0 ≤ value ≤ target time).\n</li><li><code>target time</code> (1, 2, 3): Übergebene relative Zielzeit (Ticks), repräsentiert durch <code>Gpt_ValueType</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Initial-Zustand (<code>initialized</code>):</strong>\n<ul class=\"fig-list\"><li>Voraussetzung: <code>Gpt_Init()</code> erfolgreich ausgeführt. Zählerstand verharrt auf <code>0</code>.\n</li></ul>\n</li><li><strong>Erster Zählzyklus (<code>Gpt_StartTimer 1</code> → <code>expired</code>):</strong>\n<ul class=\"fig-list\"><li>Aufruf von <code>Gpt_StartTimer(Channel, target time 1)</code>.\n</li><li>Zustandsübergang: <code>initialized</code> → <code>running</code>.\n</li><li>Zählerstand steigt deterministisch von <code>0</code> bis <code>target time 1</code>.\n</li><li>Bei Erreichen von <code>target time 1</code>: Automatischer Stop des Zählers, Übergang <code>running</code> → <code>expired</code>.\n</li><li>Falls Benachrichtigung über <code>Gpt_EnableNotification(Channel)</code> aktiviert ist, erfolgt an diesem Punkt der asynchrone Interrupt-Callback (<code>GptNotification</code>).\n</li><li>Zählerstand verbleibt bis zum nächsten API-Aufruf auf <code>target time 1</code>.\n</li></ul>\n</li><li><strong>Zweiter Zählzyklus mit vorzeitigem Abbruch (<code>Gpt_StartTimer 2</code> → <code>stopped</code>):</strong>\n<ul class=\"fig-list\"><li>Aufruf von <code>Gpt_StartTimer(Channel, target time 2)</code>.\n</li><li>Zähler wird unmittelbar auf <code>0</code> zurückgesetzt; Übergang <code>expired</code> → <code>running</code>.\n</li><li>Zähler läuft in Richtung <code>target time 2</code>.\n</li><li>Vor Erreichen des Zielwerts erfolgt der Aufruf von <code>Gpt_StopTimer(Channel)</code>.\n</li><li>Übergang <code>running</code> → <code>stopped</code>. Die Zählung wird eingefroren; es wird <strong>kein</strong> Ablauf-Callback ausgelöst.\n</li></ul>\n</li><li><strong>Dritter Zählzyklus (<code>Gpt_StartTimer 3</code> → <code>expired</code>):</strong>\n<ul class=\"fig-list\"><li>Aufruf von <code>Gpt_StartTimer(Channel, target time 3)</code>.\n</li><li>Zähler wird aus dem Zustand <code>stopped</code> wieder auf <code>0</code> zurückgesetzt; Übergang <code>stopped</code> → <code>running</code>.\n</li><li>Zähler läuft linear bis <code>target time 3</code> und wechselt bei Zielerreichung wieder nach <code>expired</code> (Zählerstand bleibt auf <code>target time 3</code> stehen, ggf. Callback).\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Automatischer Stopp:</strong> Im Gegensatz zum <code>GPT_CH_MODE_CONTINUOUS</code> erfolgt kein Rollover auf <code>0</code> und kein automatischer Neustart des Timers. Der Kanal verbleibt nach Zielerreichung inaktiv im Zustand <code>expired</code>.\n</li><li><strong>Re-Start-Verhalten:</strong> Jeder Aufruf von <code>Gpt_StartTimer()</code> auf einen bereits laufenden, angehaltenen oder abgelaufenen Kanal setzt den Zählerwert implizit auf <code>0</code> zurück.\n</li><li><strong>Abfrage von Rest- und Ablaufzeiten:</strong>\n<ul class=\"fig-list\"><li><code>Gpt_GetTimeElapsed()</code>: Liefert im Zustand <code>running</code> die bisher verstrichene Zeit ab <code>0</code>. Im Zustand <code>expired</code> liefert die Funktion normativ den vollen Zielwert (<code>target time</code>). Im Zustand <code>stopped</code> liefert sie den eingefrorenen Zwischenwert zum Zeitpunkt von <code>Gpt_StopTimer()</code>.\n</li><li><code>Gpt_GetTimeRemaining()</code>: Liefert im Zustand <code>running</code> (target time - timer value). Im Zustand <code>expired</code> ist der Rückgabewert <code>0</code>.\n</li></ul>\n</li><li><strong>Einschränkungen &amp; Fehlerbehandlung:</strong>\n<ul class=\"fig-list\"><li>Ein erneuter Aufruf von <code>Gpt_StartTimer()</code> auf einen Kanal im Zustand <code>running</code> erfordert die Einhaltung der Re-Entranz- und Zustandskonventionen (ggf. DET-Fehler <code>GPT_E_ALREADY_RUNNING</code>, sofern im Treiber so konfiguriert/spezifiziert).\n</li><li><code>Gpt_StopTimer()</code> auf einen nicht laufenden Kanal (<code>initialized</code>, <code>stopped</code>, <code>expired</code>) ist idempotent bzw. darf zu keinem undefinierten Hardwarezustand führen (prüfen auf DET-Meldung <code>GPT_E_PARAM_CHANNEL</code> oder Statusprüfung).\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-c4239e08bbeb59d2", "releases": ["R23-11", "R24-11", "R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> Zeitverlaufsdiagramm / Timing-Diagramm (Signallauf- und Kanalzustandsdiagramm über der Zeitachse t).\n</li><li><strong>Architektur-Einordnung:</strong> AUTOSAR Classic Platform, Microcontroller Abstraction Layer (MCAL), Modul <strong>GPT Driver</strong> (<code>Gpt</code>, General Purpose Timer Driver).\n</li><li><strong>Technischer Zweck:</strong> Spezifikation des Kanalverhaltens, des Zählerstands (<code>timer value</code>) und der diskreten Kanalzustände eines GPT-Hardware-/Software-Kanals im Einmal-Modus (<strong>One-Shot Mode</strong>, Konfigurationsparameter <code>GptChannelMode = GPT_CH_MODE_ONESHOT</code>) bei Aufruf der Steuerungs-APIs <code>Gpt_StartTimer()</code> und <code>Gpt_StopTimer()</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Entitäten &amp; Zustände (Kanal-Zustandsmodell):</strong>\n<ul class=\"fig-list\"><li><code>initialized</code>: Kanal nach <code>Gpt_Init()</code> initialisiert, Zähler ruht auf <code>0</code>.\n</li><li><code>running</code>: Zähler zählt aktiv aufwärts (<code>timer value</code> steigt linear) in Richtung des übergebenen Zielwerts (<code>target time</code>).\n</li><li><code>expired</code>: Zähler hat <code>target time</code> erreicht. Im One-Shot-Modus stoppt die Hardware/Software-Zählung automatisch; der Endwert bleibt gehalten.\n</li><li><code>stopped</code>: Zähler wurde vor Ablauf durch Software manuell angehalten; der erreichte Zwischenwert bleibt eingefroren.\n</li></ul>\n</li><li><strong>Schnittstellen &amp; Parameter:</strong>\n<ul class=\"fig-list\"><li><code>Gpt_StartTimer(Gpt_ChannelType Channel, Gpt_ValueType Value)</code>: Startet oder reinitialisiert den Kanal ab Relativwert <code>0</code> bis zum Zielwert <code>target time</code> (Value).\n</li><li><code>Gpt_StopTimer(Gpt_ChannelType Channel)</code>: Stoppt die Zählung asynchron/synchron; fixiert den aktuellen Zählerstand.\n</li></ul>\n</li><li><strong>Datenstrukturen &amp; Attribute:</strong>\n<ul class=\"fig-list\"><li><code>timer value</code>: Hardware-Zählerregister bzw. software-emulierter Kanalwert (0 ≤ value ≤ target time).\n</li><li><code>target time</code> (1, 2, 3): Übergebene relative Zielzeit (Ticks), repräsentiert durch <code>Gpt_ValueType</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Initial-Zustand (<code>initialized</code>):</strong>\n<ul class=\"fig-list\"><li>Voraussetzung: <code>Gpt_Init()</code> erfolgreich ausgeführt. Zählerstand verharrt auf <code>0</code>.\n</li></ul>\n</li><li><strong>Erster Zählzyklus (<code>Gpt_StartTimer 1</code> → <code>expired</code>):</strong>\n<ul class=\"fig-list\"><li>Aufruf von <code>Gpt_StartTimer(Channel, target time 1)</code>.\n</li><li>Zustandsübergang: <code>initialized</code> → <code>running</code>.\n</li><li>Zählerstand steigt deterministisch von <code>0</code> bis <code>target time 1</code>.\n</li><li>Bei Erreichen von <code>target time 1</code>: Automatischer Stop des Zählers, Übergang <code>running</code> → <code>expired</code>.\n</li><li>Falls Benachrichtigung über <code>Gpt_EnableNotification(Channel)</code> aktiviert ist, erfolgt an diesem Punkt der asynchrone Interrupt-Callback (<code>GptNotification</code>).\n</li><li>Zählerstand verbleibt bis zum nächsten API-Aufruf auf <code>target time 1</code>.\n</li></ul>\n</li><li><strong>Zweiter Zählzyklus mit vorzeitigem Abbruch (<code>Gpt_StartTimer 2</code> → <code>stopped</code>):</strong>\n<ul class=\"fig-list\"><li>Aufruf von <code>Gpt_StartTimer(Channel, target time 2)</code>.\n</li><li>Zähler wird unmittelbar auf <code>0</code> zurückgesetzt; Übergang <code>expired</code> → <code>running</code>.\n</li><li>Zähler läuft in Richtung <code>target time 2</code>.\n</li><li>Vor Erreichen des Zielwerts erfolgt der Aufruf von <code>Gpt_StopTimer(Channel)</code>.\n</li><li>Übergang <code>running</code> → <code>stopped</code>. Die Zählung wird eingefroren; es wird <strong>kein</strong> Ablauf-Callback ausgelöst.\n</li></ul>\n</li><li><strong>Dritter Zählzyklus (<code>Gpt_StartTimer 3</code> → <code>expired</code>):</strong>\n<ul class=\"fig-list\"><li>Aufruf von <code>Gpt_StartTimer(Channel, target time 3)</code>.\n</li><li>Zähler wird aus dem Zustand <code>stopped</code> wieder auf <code>0</code> zurückgesetzt; Übergang <code>stopped</code> → <code>running</code>.\n</li><li>Zähler läuft linear bis <code>target time 3</code> und wechselt bei Zielerreichung wieder nach <code>expired</code> (Zählerstand bleibt auf <code>target time 3</code> stehen, ggf. Callback).\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Automatischer Stopp:</strong> Im Gegensatz zum <code>GPT_CH_MODE_CONTINUOUS</code> erfolgt kein Rollover auf <code>0</code> und kein automatischer Neustart des Timers. Der Kanal verbleibt nach Zielerreichung inaktiv im Zustand <code>expired</code>.\n</li><li><strong>Re-Start-Verhalten:</strong> Jeder Aufruf von <code>Gpt_StartTimer()</code> auf einen bereits laufenden, angehaltenen oder abgelaufenen Kanal setzt den Zählerwert implizit auf <code>0</code> zurück.\n</li><li><strong>Abfrage von Rest- und Ablaufzeiten:</strong>\n<ul class=\"fig-list\"><li><code>Gpt_GetTimeElapsed()</code>: Liefert im Zustand <code>running</code> die bisher verstrichene Zeit ab <code>0</code>. Im Zustand <code>expired</code> liefert die Funktion normativ den vollen Zielwert (<code>target time</code>). Im Zustand <code>stopped</code> liefert sie den eingefrorenen Zwischenwert zum Zeitpunkt von <code>Gpt_StopTimer()</code>.\n</li><li><code>Gpt_GetTimeRemaining()</code>: Liefert im Zustand <code>running</code> (target time - timer value). Im Zustand <code>expired</code> ist der Rückgabewert <code>0</code>.\n</li></ul>\n</li><li><strong>Einschränkungen &amp; Fehlerbehandlung:</strong>\n<ul class=\"fig-list\"><li>Ein erneuter Aufruf von <code>Gpt_StartTimer()</code> auf einen Kanal im Zustand <code>running</code> erfordert die Einhaltung der Re-Entranz- und Zustandskonventionen (ggf. DET-Fehler <code>GPT_E_ALREADY_RUNNING</code>, sofern im Treiber so konfiguriert/spezifiziert).\n</li><li><code>Gpt_StopTimer()</code> auf einen nicht laufenden Kanal (<code>initialized</code>, <code>stopped</code>, <code>expired</code>) ist idempotent bzw. darf zu keinem undefinierten Hardwarezustand führen (prüfen auf DET-Meldung <code>GPT_E_PARAM_CHANNEL</code> oder Statusprüfung).\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-e2f23961438a99d3", "to": "FIG-188d25463dd994b3", "fr": "R4.0.3", "tr": "R4.1.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-188d25463dd994b3", "to": "FIG-452b75e78c57ec25", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-452b75e78c57ec25", "to": "FIG-482483b750955172", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-482483b750955172", "to": "FIG-c4239e08bbeb59d2", "fr": "R22-11", "tr": "R23-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
